function validatedR3SubstituteDecisionCandidates(value, scope) {
  if (value?.branchId !== scope.branchId || value?.coachRoleId !== scope.coachRoleId
    || String(value?.settlementMonth || "").slice(0, 10) !== scope.settlementMonth
    || !Array.isArray(value?.candidates) || value.candidates.length > 500) {
    throw new Error("settlement_substitute_candidate_scope_mismatch");
  }
  const seen = new Set();
  for (const item of value.candidates) {
    if (!/^[0-9a-f-]{36}$/i.test(String(item?.id || "")) || seen.has(item.id)
      || item.branchId !== scope.branchId
      || !/^[0-9a-f-]{36}$/i.test(String(item.lessonId || ""))
      || !Number.isSafeInteger(Number(item.lessonRevision))
      || String(item.serviceDate || "").slice(0, 7) !== scope.settlementMonth.slice(0, 7)
      || ![item.originalCoachRoleId, item.actualCoachRoleId].includes(scope.coachRoleId)
      || !/^[0-9a-f]{64}$/.test(String(item.sourceFingerprint || ""))) {
      throw new Error("settlement_substitute_candidate_scope_mismatch");
    }
    seen.add(item.id);
  }
  return value.candidates;
}

const code = String(error?.payload?.message || error?.message || "");
const errorCode = code.includes("settlement_hold_substitute_manual_approval_required")
  ? "settlement_hold_substitute_manual_approval_required" : "";
if (!errorCode) return { coach, error: window.TennisNoteSettlementAdjustment.effectiveError(error), errorCode: "" };
try {
  const listed = await client.rpc("tn_admin_list_substitute_manual_candidates", {
    target_branch_id: branchId, target_coach_role_id: coach.serverRoleId, target_month: settlementMonth,
  });
  if (!requestIsCurrent()) return null;
  const candidates = validatedR3SubstituteDecisionCandidates(listed, scope);
  return { coach, error: window.TennisNoteSettlementAdjustment.effectiveError(error), errorCode,
    candidates, candidateLoadError: candidates.length ? "" : "정확한 대타 귀속 근거를 찾지 못했습니다." };
} catch (_) {
  if (!requestIsCurrent()) return null;
  return { coach, error: window.TennisNoteSettlementAdjustment.effectiveError(error), errorCode,
    candidates: [], candidateLoadError: "대타 귀속 근거를 불러오지 못했습니다. 저장은 차단됐습니다." };
}

const r3SubstituteDecisionUi = { preview: null, recipient: "", operationKey: "", busy: false, message: "" };

function r3SubstituteDecisionCandidates(coach) {
  const entries = effectiveSettlementPreview.results.filter((item) => item.coach.serverRoleId === coach.serverRoleId);
  return entries.length === 1 && entries[0].errorCode === "settlement_hold_substitute_manual_approval_required"
    && effectiveSettlementPreviewContextIsCurrent(effectiveSettlementPreview.context)
    ? entries[0].candidates || [] : [];
}

async function previewR3SubstituteDecision(assignmentId) {
  if (r3SubstituteDecisionUi.busy || !adminApprovalReady()) return;
  const context = effectiveSettlementPreviewContext();
  if (!effectiveSettlementPreviewContextIsCurrent(context)) return;
  const candidate = effectiveSettlementPreview.results.flatMap((entry) => entry.candidates || [])
    .find((item) => item.id === assignmentId);
  if (!candidate || candidate.branchId !== activeOperationBranchId()) return;
  r3SubstituteDecisionUi.busy = true;
  r3SubstituteDecisionUi.message = "대타 귀속 근거를 확인하고 있습니다.";
  renderEffectiveSettlementPreview();
  try {
    const value = await context.client.rpc("tn_admin_preview_substitute_policy_decision", {
      target_branch_id: activeOperationBranchId(), target_assignment_id: assignmentId,
    });
    if (!effectiveSettlementPreviewContextIsCurrent(context) || value.branchId !== candidate.branchId
      || value.assignmentId !== assignmentId || value.lessonId !== candidate.lessonId
      || Number(value.lessonRevision) !== Number(candidate.lessonRevision)
      || value.sourceFingerprint !== candidate.sourceFingerprint) return;
    r3SubstituteDecisionUi.preview = value;
    r3SubstituteDecisionUi.recipient = "";
    r3SubstituteDecisionUi.operationKey = "";
    r3SubstituteDecisionUi.message = value.decisionEnabled ? "원 담당 A와 실제 대타 B 중 귀속을 확인해 주세요."
      : "대타 귀속 승인 기능은 현재 OFF입니다. 운영 게이트 확인 전 저장할 수 없습니다.";
  } catch (error) {
    if (effectiveSettlementPreviewContextIsCurrent(context)) r3SubstituteDecisionUi.message = window.TennisNoteSettlementAdjustment.effectiveError(error);
  } finally {
    r3SubstituteDecisionUi.busy = false;
    if (effectiveSettlementPreviewContextIsCurrent(context)) renderEffectiveSettlementPreview();
  }
}

async function confirmR3SubstituteDecision() {
  const decision = r3SubstituteDecisionUi.preview;
  if (r3SubstituteDecisionUi.busy || !decision?.decisionEnabled || decision.chosenRecipient
    || !["originalCoach", "actualCoach"].includes(r3SubstituteDecisionUi.recipient)) return;
  const context = effectiveSettlementPreviewContext();
  if (!effectiveSettlementPreviewContextIsCurrent(context) || decision.branchId !== activeOperationBranchId()
    || !effectiveSettlementPreview.results.some((entry) => (entry.candidates || []).some((candidate) =>
      candidate.id === decision.assignmentId && candidate.sourceFingerprint === decision.sourceFingerprint))) return;
  r3SubstituteDecisionUi.operationKey ||= createAdminOperationKey("r3-substitute-decision");
  r3SubstituteDecisionUi.busy = true;
  renderEffectiveSettlementPreview();
  try {
    const result = await context.client.rpc("tn_admin_confirm_substitute_policy_decision", {
      target_branch_id: decision.branchId, target_assignment_id: decision.assignmentId,
      expected_lesson_revision: decision.lessonRevision, expected_source_fingerprint: decision.sourceFingerprint,
      target_chosen_recipient: r3SubstituteDecisionUi.recipient,
      target_operation_key: r3SubstituteDecisionUi.operationKey,
    });
    if (!effectiveSettlementPreviewContextIsCurrent(context) || result?.ok !== true) return;
    r3SubstituteDecisionUi.preview = null;
    r3SubstituteDecisionUi.message = "대타 귀속을 기록했습니다. 서버 정산을 다시 확인합니다.";
    void refreshEffectiveSettlementPreview(effectiveSettlementPreviewSignature());
  } catch (error) {
    if (effectiveSettlementPreviewContextIsCurrent(context)) r3SubstituteDecisionUi.message = window.TennisNoteSettlementAdjustment.effectiveError(error);
  } finally {
    r3SubstituteDecisionUi.busy = false;
    if (effectiveSettlementPreviewContextIsCurrent(context)) renderEffectiveSettlementPreview();
  }
}

.map(({ coach, row, error, errorCode, candidateLoadError }) => {
  if (error) {
    const candidates = errorCode === "settlement_hold_substitute_manual_approval_required"
      ? r3SubstituteDecisionCandidates(coach) : [];
    const actions = candidates.map((assignment, index) =>
      `<button type="button" data-r3-policy-preview="${escapeHtml(assignment.id)}" ${r3SubstituteDecisionUi.busy ? "disabled" : ""}>대타 귀속 근거 ${index + 1} 확인</button>`).join(" ");
    const decision = r3SubstituteDecisionUi.preview;
    const chooser = decision && candidates.some((assignment) => assignment.id === decision.assignmentId)
      ? `<label>대타 정산 귀속 <select data-r3-policy-recipient ${decision.decisionEnabled && !decision.chosenRecipient && !r3SubstituteDecisionUi.busy ? "" : "disabled"}>
          <option value="">선택</option><option value="originalCoach" ${r3SubstituteDecisionUi.recipient === "originalCoach" ? "selected" : ""}>A 원 담당 코치</option>
          <option value="actualCoach" ${r3SubstituteDecisionUi.recipient === "actualCoach" ? "selected" : ""}>B 실제 대타 코치</option></select></label>
          <button type="button" data-r3-policy-confirm ${decision.decisionEnabled && !decision.chosenRecipient && r3SubstituteDecisionUi.recipient && !r3SubstituteDecisionUi.busy ? "" : "disabled"}>귀속 확인 저장</button>` : "";
    return `<tr><td colspan="6">${escapeHtml(coach.name)} · ${escapeHtml(error)} ${actions} ${chooser}
      ${candidateLoadError ? `<small>${escapeHtml(candidateLoadError)}</small>` : ""}
      <small role="status">${escapeHtml(r3SubstituteDecisionUi.message)}</small></td></tr>`;
  }

rows.querySelectorAll("[data-r3-policy-preview]").forEach((button) => button.addEventListener("click", () => {
  void previewR3SubstituteDecision(button.dataset.r3PolicyPreview);
}));
rows.querySelector("[data-r3-policy-recipient]")?.addEventListener("change", (event) => {
  r3SubstituteDecisionUi.recipient = event.target.value;
  r3SubstituteDecisionUi.operationKey = "";
  renderEffectiveSettlementPreview();
});
rows.querySelector("[data-r3-policy-confirm]")?.addEventListener("click", () => void confirmR3SubstituteDecision());

if (value.totals.ownSettlementAmount + value.totals.substituteSettlementAmount !== value.totals.totalSettlementAmount) {
  throw new Error("settlement_split_total_mismatch");
}
const policyV2 = value.sourceManifest?.substituteContractVersion === "r3_substitute_policy_v2";
if (!policyV2 && value.sourceManifest?.substituteContractVersion !== "r3_substitute_safe_v1"
  && value.lines.some((line) => line.lineKind === "substitute_session")) {
  throw new Error("settlement_substitute_contract_unknown");
}
if (policyV2 && (!Number.isSafeInteger(value.totals?.branchSubstituteExpenseAmount)
  || value.totals.branchSubstituteExpenseAmount < 0
  || value.totals.branchSubstituteExpenseAmount > value.totals.substituteSettlementAmount)) {
  throw new Error("settlement_branch_expense_total_invalid");
}
const lineIndexes = new Set();
const contributions = new Set();
const physicalSources = new Map();
const split = { own_payment: 0, substitute_session: 0 };
let branchExpense = 0;
for (const line of value.lines) {
  if (!Number.isSafeInteger(line.lineIndex) || line.lineIndex <= 0 || lineIndexes.has(line.lineIndex)
    || !Object.hasOwn(split, line.lineKind)
    || !Number.isSafeInteger(line.settlementAmount) || line.settlementAmount < 0) {
    throw new Error("settlement_line_scope_mismatch");
  }
  lineIndexes.add(line.lineIndex);
  for (const key of ["settledSessions", "settledMinutes", "totalSessions", "netAmount"]) {
    if (!Number.isSafeInteger(line[key]) || line[key] < 0) throw new Error("settlement_line_scope_mismatch");
  }
  if (line.lineKind === "substitute_session" && (!line.sourceLessonId || !line.sourceSessionId || !line.sourceSubstituteAssignmentId)) {
    throw new Error("settlement_substitute_source_missing");
  }
  if (line.lineKind === "substitute_session") {
    const components = line.calculationComponents;
    const key = components?.physicalKey;
    // Server UUID/date/time keys are bounded; never normalize distinct source handles.
    if (typeof key !== "string" || !key || key.length > 512 || key !== key.trim()
      || /[\u0000-\u001f\u007f]/.test(key) || !Array.isArray(components.contributions)) {
      throw new Error("settlement_substitute_physical_key_invalid");
    }
    const source = physicalSources.get(key) || {
      lessonId: line.sourceLessonId, assignmentId: line.sourceSubstituteAssignmentId,
      payable: false, nonPayable: false,
    };
    if (source.lessonId !== line.sourceLessonId || source.assignmentId !== line.sourceSubstituteAssignmentId) {
      throw new Error("settlement_substitute_physical_source_conflict");
    }
    const exactSession = policyV2
      ? (value.sourceManifest.sessions || []).filter((item) => item.id === line.sourceSessionId)
      : [];
    if (policyV2 && (exactSession.length !== 1 || exactSession[0].lessonId !== line.sourceLessonId
      || exactSession[0].substituteAssignmentId !== line.sourceSubstituteAssignmentId
      || exactSession[0].accountingClass !== components.accountingClass)) {
      throw new Error("settlement_substitute_accounting_source_mismatch");
    }
    if (components.duplicateSharedTime === true) {
      if (line.settlementAmount !== 0 || line.settledSessions !== 0 || line.settledMinutes !== 0
        || components.contributions.length !== 0) {
        throw new Error("settlement_substitute_duplicate_trace_invalid");
      }
      if (policyV2 && components.nonPayableDecision === true) source.nonPayable = true;
    } else {
      if (line.settledSessions <= 0 || components.contributions.length === 0
        || components.contributions.some((item) => !item || item.sessionId !== line.sourceSessionId
          || item.lessonId !== line.sourceLessonId || item.substituteAssignmentId !== line.sourceSubstituteAssignmentId)) {
        throw new Error("settlement_substitute_payable_source_invalid");
      }
      source.payable = true; // A valid occurrence can have a legitimate zero-won payout.
      if (policyV2 && components.accountingClass === "branch_substitute_expense") {
        branchExpense += line.settlementAmount;
      }
    }
    physicalSources.set(key, source);
  }
  for (const item of line.calculationComponents?.contributions || []) {
    const key = item.sessionId ? `session:${item.sessionId}` : item.paymentId ? `payment:${item.paymentId}` : "";
    if (!key || contributions.has(key)) throw new Error("settlement_contribution_duplicate_or_missing");
    contributions.add(key);
  }
  split[line.lineKind] += line.settlementAmount;
}
if ([...physicalSources.values()].some((source) => source.payable === source.nonPayable
  || (!source.payable && !policyV2))) {
  throw new Error("settlement_substitute_duplicate_trace_orphan");
}
if ([...physicalSources.values()].filter((source) => source.payable).length !== value.totals.substituteSessionCount) {
  throw new Error("settlement_substitute_physical_count_mismatch");
}
if (policyV2 && branchExpense !== value.totals.branchSubstituteExpenseAmount) {
  throw new Error("settlement_branch_expense_total_mismatch");
}
if (split.own_payment !== value.totals.ownSettlementAmount || split.substitute_session !== value.totals.substituteSettlementAmount) {
  throw new Error("settlement_split_line_mismatch");
}

if (ticketById.size !== value.sourceManifest.tickets.length || ticketById.has(undefined) || ticketById.has(null)) {
  throw new Error("settlement_ticket_source_ambiguous");
}

if (line.lineKind === "own_payment" && ticket.coachRoleId !== scope.coachRoleId) {
  throw new Error("settlement_line_scope_mismatch");
}
if (line.lineKind === "substitute_session") {
  const exact = (value.sourceManifest.assignments || []).filter((item) => item.id === line.sourceSubstituteAssignmentId);
  const session = policyV2 ? (value.sourceManifest.sessions || []).find((item) => item.id === line.sourceSessionId) : null;
  if (exact.length !== 1
    || exact[0].lessonId !== line.sourceLessonId || exact[0].branchId !== scope.branchId
    || exact[0].substituteCoachRoleId !== scope.coachRoleId || exact[0].originalCoachRoleId !== ticket.coachRoleId
    || !["assigned", "completed"].includes(exact[0].status)
    || (policyV2
      ? !["actual_coach", "hourly", "none"].includes(exact[0].settlementMode)
        || !session || session.substituteSettlementMode !== exact[0].settlementMode
        || (line.calculationComponents?.nonPayableDecision === true
          ? session.recipientCoachRoleId === scope.coachRoleId
          : session.recipientCoachRoleId !== scope.coachRoleId)
      : exact[0].settlementMode !== "actual_coach")) {
    throw new Error("settlement_substitute_source_mismatch");
  }
}

const substituteDetail = (row) => {
  const components = row.calculationComponents || {};
  const formulas = (components.contributions || []).map((item) => item.formula);
  const basis = components.duplicateSharedTime === true ? ""
    : formulas.length && formulas.every((formula) => formula === "hourly") ? "시간제 근거"
      : formulas.length && formulas.every((formula) => formula === "session_progress") ? "회원권 결제 근거" : "적용기간별 계산 근거";
  const peerMinutes = typeof components.physicalKey === "string" && components.physicalKey
    && row.sourceLessonId && row.sourceSubstituteAssignmentId && row.coachRoleId
    ? rows.filter((peer) => peer.lineKind === "substitute_session"
      && peer.calculationComponents?.physicalKey === components.physicalKey
      && peer.sourceLessonId === row.sourceLessonId && peer.sourceSubstituteAssignmentId === row.sourceSubstituteAssignmentId
      && peer.coachRoleId === row.coachRoleId && Number.isSafeInteger(peer.settledMinutes) && peer.settledMinutes > 0
      && peer.settledSessions > 0 && peer.calculationComponents?.duplicateSharedTime !== true
      && Array.isArray(peer.calculationComponents?.contributions) && peer.calculationComponents.contributions.length > 0)
      .map((peer) => peer.settledMinutes) : [];
  const occurrenceMinutes = new Set(peerMinutes).size === 1 ? peerMinutes[0] : null;
  const progress = Number.isSafeInteger(row.settledMinutes) && row.settledMinutes > 0
    ? `실제 진행 ${row.settledMinutes}분`
    : occurrenceMinutes ? `공동 수업 ${occurrenceMinutes}분` : "수업 시간 확인 필요";
  const exclusion = components.duplicateSharedTime === true ? "시간·정산 중복 제외"
    : row.settledMinutes === 0 ? "시간 합계 중복 제외" : "";
  return [progress, `정산 ${Number(row.settledSessions) || 0}회`, basis, exclusion].filter(Boolean).join(" · ");
};
